<template><section aria-label="科研队列完整来源明确选择"><el-alert title="请选择当前项目中已授权、已发布的病例来源。" type="info" :closable="false" /><p v-if="!v.referencesValid" role="alert">科研来源引用不合法；不会转为其他输入模式或接受其他病例别名。</p><p v-else-if="!v.authorized" role="status">当前会话或角色不能选择本项来源。</p><template v-else><el-button :disabled="v.busy" @click="v.showSources">打开科研病例来源目录</el-button><el-button v-if="v.preset||v.selected" :loading="v.busy" @click="v.reread">重新核对明确科研病例来源</el-button><el-button v-if="v.selected" @click="v.clear({close:true})">清除本次科研来源选择</el-button><p v-if="v.selected" role="status">已明确选择项目 {{ v.selected.anchors.scope_id }} 的完整病例来源 {{ v.selected.anchors.case_id }}；已清除完整原文和私人授权依据。</p><p v-else>尚未建立当前完整来源选择；不会自动选择第一项。</p><p v-if="v.selected&&v.selected.externalModelUse!=='recorded_permitted'" role="status">本项目尚未记录明确外部模型处理许可；已核对的本地条件结果不授予模型调用权限。</p><div v-if="v.open" aria-label="本次科研病例来源目录"><el-button @click="v.closeSources">关闭本次科研来源目录</el-button><ResearchCohortSources :active="active&&v.open" :audit-only="false" @select="v.select" @invalidate="v.invalidate" @source-changed="v.sourceChanged" /></div></template><p v-if="v.error" role="alert">{{ v.error }}</p></section></template>
<script setup>
import {reactive} from 'vue';
import ResearchCohortSources from './ResearchCohortSources.vue';
import {useResearchCohortSourceInput} from './useResearchCohortSourceInput';
const props=defineProps({initialReferences:{type:Object,default:null},active:{type:Boolean,default:true}}),emit=defineEmits(['scope-change','selection','availability','invalidate']),v=reactive(useResearchCohortSourceInput(props,emit));
